// Frozen Build518 AI baseline for controlled comparisons only. Never imported by the product.
import {TOWER517,solid517,random517,shape517,landing517,fits517,aim517,drop517} from '../../src/tower/Rules517.js';
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const overlap=(a,b,c,d)=>a<d-1e-6&&b>c+1e-6;
function surface(g,p,x=p.x){let height=0,support=null;const left=x-TOWER517.pw/2,right=x+TOWER517.pw/2;for(const b of g.board)if(overlap(left,right,b.x,b.x+1)&&b.y+1<=p.y+.035&&b.y+1>height)height=b.y+1;
 for(const o of g.players)if(o!==p&&o.role==='run'&&o.alive&&!o.escaped&&overlap(left,right,o.x-TOWER517.pw/2,o.x+TOWER517.pw/2)&&o.y+TOWER517.ph<=p.y+.045&&o.y+TOWER517.ph>height){height=o.y+TOWER517.ph;support=o.playerId}return{height,support}}
export function runner518(g,p){if(!p.alive)return{axis:0};const danger=g.falling?.cells.filter(([dx])=>Math.abs(g.falling.x+dx+.5-p.x)<1.1)??[];if(danger.length&&g.falling.y<p.y+4){const f=g.falling,center=f.x+(Math.max(...f.cells.map(c=>c[0]))+1)/2;const axis=p.x<center?(p.x>.6?-1:1):(p.x<9.4?1:-1);return{axis,dash:g.falling.y<p.y+3,jump:p.grounded&&solid517(g,p.x+axis*.45,p.y,false)}}
 if(g.elapsed>=(p.botNext??0)){p.botNext=g.elapsed+350;const options=[];for(let x=.5;x<10;x++){const q={...p,y:p.y+2.12},s=surface(g,q,x);if(s.height<=p.y+2.12&&Math.abs(x-p.x)<3.8&&!solid517(g,x,s.height,false)){let blocked=false;for(let probe=p.x;Math.abs(probe-x)>.2;probe+=Math.sign(x-p.x)*.2){if(solid517(g,probe,p.y+2.02,false)){blocked=true;break}}if(blocked)continue;const dangerX=g.falling?.cells.some(([dx])=>Math.abs(g.falling.x+dx+.5-x)<.8);options.push({x,h:s.height,score:s.height*3-Math.abs(x-p.x)*.28-(dangerX?7:0)+(random517(g,10)/35)})}}options.sort((a,b)=>b.score-a.score);p.botTarget=options[0]?.x??p.x}
 const axis=Math.abs((p.botTarget??p.x)-p.x)>.15?Math.sign(p.botTarget-p.x):0;const target=surface(g,{...p,y:p.y+2.12},p.botTarget??p.x).height;const wall=solid517(g,p.x+axis*.42,p.y,false);return{axis,jump:p.grounded&&(target>p.y+.1||wall||g.elapsed>(p.botJump??0)&&(p.botJump=g.elapsed+900+random517(g,800))),dash:false}}
export function dropper518(g){if(g.falling||g.elapsed<g.nextDropAt)return;if(g.elapsed<(g.botDropAt??0))return;const alive=g.players.filter(p=>p.role==='run'&&p.alive);const target=alive[random517(g,Math.max(1,alive.length))];if(!target)return;let best=null;for(let slot=0;slot<4;slot++)for(let rot=0;rot<4;rot++){const cells=shape517(g.hand[slot],rot),w=Math.max(...cells.map(c=>c[0]))+1;for(let x=0;x<=10-w;x++){const land=landing517(g,cells,x);if(!fits517(g,cells,x))continue;const near=cells.some(([dx])=>Math.abs(x+dx+.5-target.x)<.7),score=(near?2.2:0)-Math.abs(x+w/2-target.x)*.15-land*.70+random517(g,100)/45;if(!best||score>best.score)best={slot,rot,x,score}}}if(!best){g.botDropAt=g.elapsed+500;return}aim517(g,best.slot,best.rot,best.x);drop517(g);g.botDropAt=g.elapsed+1800-900*clamp(g.elapsed/TOWER517.duration,0,1)}
